  --_accent-text: var(--color-content-utility-danger);
}
.esa-nav-dropdown .esa-button__native > .esa-icon:last-child {
  transition: transform 0.15s ease;
}
.cbf-lct__grab > .stack {
  flex: 1;
  min-width: 0;
}
.cbf-lsr__name {
  margin: 0;
}
.cbf-lsr__scope,
.cbf-lsr__note {
  margin: 0;
