    --typography-font-weight-medium,
    var(--typography-label-md-font-weight, var(--typography-font-weight-medium, 500))
  );
  --_stat-sub-color: var(--color-content-default-secondary, #646464);
  --_stat-sub-size: var(
    --font-size-150,
    var(--typography-body-sm-font-size, var(--font-size-150, 0.875rem))
  );
  --_stat-accent-color: var(--stat-accent-color, var(--color-content-brand, #2a7e3b));
  --_stat-gap: var(--spacing-050, 0.125rem);
  display: flex;
  flex-direction: column;
  gap: var(--_stat-gap);
  background: transparent;
}
.esa-stat__value {
  font-family: var(--_stat-value-font);
  font-size: var(--_stat-value-size);
  font-weight: var(--_stat-value-weight);
  color: var(--_stat-value-color);
}
.esa-stat__label {
  font-size: var(--_stat-label-size);
  font-weight: var(--_stat-label-weight);
  color: var(--_stat-label-color);
}
.esa-stat__sub {
  font-size: var(--_stat-sub-size);
  color: var(--_stat-sub-color);
}
:host {
  display: block;
  --_field-padding-y: var(--spacing-300, 0.75rem);
  --_field-padding-x: var(--spacing-300, 0.75rem);
  --_field-radius: var(--radius-md, 0.5rem);
  --_field-border-color: var(--form-border-color, #cecece);
}
.field {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-100, 4px);
}
.container {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-100, 4px);
}
.input-wrapper {
  position: relative;
  display: flex;
  align-items: center;
}
.input {
  width: 100%;
  padding: var(--_field-padding-y) var(--_field-padding-x);
  padding-inline-end: calc(var(--_field-padding-x) + 24px);
  /* Leading is load-bearing on a content-sized box — see the long note in
         esa-select's .input. Single line, so the composite's relaxed leading only
         adds height. */
  color: var(--form-text-color, #202020);
  background: var(--color-background-field, transparent);
  border: var(--form-border-width, 1px) solid var(--_field-border-color);
  border-radius: var(--_field-radius);
  outline: none;
  box-sizing: border-box;
  transition:
    border-color var(--transition-fast, 150ms ease),
    box-shadow var(--transition-fast, 150ms ease);
}
.input::placeholder {
  color: var(--form-placeholder-color, #838383);
}
.field__error {
  display: flex;
  align-items: center;
  gap: var(--spacing-100, 4px);
  color: var(--form-error-color, var(--color-content-utility-danger, #ce2c31));
}
.field__help {
  color: var(--form-help-color, #838383);
}
.esa-card {
  --_card-bg: var(--card-bg, var(--color-background-elevation-raised, #fcfcfc));
  --_card-border: var(--card-border-color, var(--color-border-default, #cecece));
  --_card-radius: var(--radius-md, 0.5rem);
  --_card-padding: var(--spacing-500, 1.5rem);
  --_card-header-bg: var(--card-header-bg, transparent);
  --_card-header-color: var(--color-content-default, #202020);
  --_card-header-border: var(--color-border-default-subtle, #d9d9d9);
  display: block;
  background: var(--_card-bg);
  border: var(--border-width-default, 1px) solid var(--_card-border);
  border-radius: var(--_card-radius);
  overflow: hidden;
}
.esa-card--filled {
  --_card-bg: var(--color-background-elevation-sunken, #f0f0f0);
  --_card-border: transparent;
}
.esa-card__body {
  padding: var(--_card-padding);
}
.esa-card--outlined {
  --_card-border: var(--color-border-default, #cecece);
}
.typography-label-xs {
  font-family: var(--typography-label-xs-font-family);
  font-size: var(--typography-label-xs-font-size);
  font-weight: var(--typography-label-xs-font-weight);
  line-height: var(--typography-label-xs-line-height);
  letter-spacing: var(--typography-label-xs-letter-spacing);
}
.typography-microcopy-xs-strong {
  font-family: var(--typography-microcopy-xs-strong-font-family);
  font-size: var(--typography-microcopy-xs-strong-font-size);
  font-weight: var(--typography-microcopy-xs-strong-font-weight);
  line-height: var(--typography-microcopy-xs-strong-line-height);
  letter-spacing: var(--typography-microcopy-xs-strong-letter-spacing);
}
.typography-microcopy-xs {
  font-family: var(--typography-microcopy-xs-font-family);
  font-size: var(--typography-microcopy-xs-font-size);
  font-weight: var(--typography-microcopy-xs-font-weight);
  line-height: var(--typography-microcopy-xs-line-height);
  letter-spacing: var(--typography-microcopy-xs-letter-spacing);
}
.typography-microcopy-md-subtle {
  font-family: var(--typography-microcopy-md-subtle-font-family);
  font-size: var(--typography-microcopy-md-subtle-font-size);
  font-weight: var(--typography-microcopy-md-subtle-font-weight);
  line-height: var(--typography-microcopy-md-subtle-line-height);
  letter-spacing: var(--typography-microcopy-md-subtle-letter-spacing);
}
.typography-microcopy-md {
  font-family: var(--typography-microcopy-md-font-family);
  font-size: var(--typography-microcopy-md-font-size);
  font-weight: var(--typography-microcopy-md-font-weight);
  line-height: var(--typography-microcopy-md-line-height);
  letter-spacing: var(--typography-microcopy-md-letter-spacing);
}
.typography-body-md {
  font-family: var(--typography-body-md-font-family);
  font-size: var(--typography-body-md-font-size);
  font-weight: var(--typography-body-md-font-weight);
  line-height: var(--typography-body-md-line-height);
  letter-spacing: var(--typography-body-md-letter-spacing);
}
.typography-body-sm {
  font-family: var(--typography-body-sm-font-family);
  font-size: var(--typography-body-sm-font-size);
  font-weight: var(--typography-body-sm-font-weight);
  line-height: var(--typography-body-sm-line-height);
  letter-spacing: var(--typography-body-sm-letter-spacing);
}
.typography-microcopy-xs-subtle {
  font-family: var(--typography-microcopy-xs-subtle-font-family);
  font-size: var(--typography-microcopy-xs-subtle-font-size);
  font-weight: var(--typography-microcopy-xs-subtle-font-weight);
  line-height: var(--typography-microcopy-xs-subtle-line-height);
  letter-spacing: var(--typography-microcopy-xs-subtle-letter-spacing);
}
:host {
  --_checkbox-size: 20px;
  --_checkbox-radius: var(--radius-md, 0.5rem);
  --_checkbox-icon-size: 16px;
  display: inline-block;
}
.wrapper {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-200, 8px);
  cursor: pointer;
  user-select: none;
}
.box {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--_checkbox-size);
  height: var(--_checkbox-size);
  flex-shrink: 0;
  /* The size token is authoritative: without this, re-pointing the indicator
         border width would resize the control instead of thickening its edge. */
  box-sizing: border-box;
  border: var(--form-border-width, 1px) solid var(--form-border-color, #cecece);
  border-radius: var(--_checkbox-radius);
  background: var(--color-background-field, transparent);
  color: var(--color-content-default-knockout, #fcfcfc);
  transition:
    background var(--transition-fast, 150ms ease),
    border-color var(--transition-fast, 150ms ease),
    box-shadow var(--transition-fast, 150ms ease);
}
.label {
  color: var(--color-content-default, #202020);
}
:host {
  display: contents;
}
dialog.esa-confirm-dialog {
  position: relative;
  border: none;
  padding: 0;
  margin: auto;
  width: var(--confirm-dialog-width, 360px);
  max-width: calc(100vw - 2rem);
  background: var(--color-background-elevation-floating, #fcfcfc);
  color: var(--color-content-default, #202020);
  border-radius: var(--radius-lg, 0.75rem);
  box-shadow:
    0 20px 60px rgba(0, 0, 0, 0.15),
    0 4px 16px rgba(0, 0, 0, 0.1);
  overflow: hidden;
  font-family: var(--typography-font-family-sans, "DM Sans", sans-serif);
}
:host {
  display: inline-block;
}
.esa-dropdown {
  position: relative;
  display: inline-block;
}
.esa-dropdown__trigger {
  display: inline-block;
}
